const params = new URLSearchParams({
  state: "FL",
  county: "Miami-Dade",
});

const res = await fetch(
  `https://www.foreclosuredatahub.com/api/v1/properties/search?${params}`,
  { headers: { "x-api-key": "fdh_ak_..." } }
);
const data = await res.json();

const params = new URLSearchParams({
  mode: "unified",
  state: "FL",
  pre_foreclosure: "true",
  page: "1",
  page_size: "25",
});

const res = await fetch(
  `https://www.foreclosuredatahub.com/api/v1/properties/search?${params}`,
  { headers: { "x-api-key": "fdh_ak_..." } }
);
const data = await res.json();

